import itertools
import math
from pandas import Series

def task_func(elements, subset_size, top_n=2):
    elements = tuple(elements)

    if subset_size < 0 or subset_size == 0 or subset_size > len(elements):
        return 1, Series(dtype=int)

    subset_sums = [sum(combo) for combo in itertools.combinations(elements, subset_size)]
    product_of_sums = math.prod(subset_sums) if subset_sums else 1

    if top_n is None or top_n <= 0:
        top_sums = Series(dtype=int)
    else:
        top_sums = Series(sorted(subset_sums, reverse=True)[:top_n])

    return product_of_sums, top_sums
